// Пины для датчика HC-SR04
const int trigPin = 9;
const int echoPin = 10;

void setup() {
  // Настраиваем пины
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  // Запускаем последовательный порт для вывода данных
  Serial.begin(9600);
}

void loop() {
  long duration, distanceCm;

  // Очищаем триггер
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  // Посылаем импульс 10 мкс
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Считываем время отклика
  duration = pulseIn(echoPin, HIGH);

  // Переводим время в расстояние (скорость звука ~340 м/с)
  distanceCm = duration * 0.034 / 2;

  // Вывод в Serial Monitor
  Serial.print("Расстояние: ");
  Serial.print(distanceCm);
  Serial.println(" см");

  delay(500); // Пауза между измерениями
}
